function c(e){const o=e.trace,r=e.cited_records.filter(t=>t.evidence.kind!=="absent").length,n=e.cited_records.some(t=>t.evidence.kind==="absent"),s=e.confidence;if(e.status==="not_evaluated")return{headline:"No score",rule:"This question was not evaluated, so there is no answer and no confidence."};if(o.router.early_abstain)return{headline:"Report not in the archive",rule:"The question names a well or date that no report covers. Abstaining is certain here, so code scores it 0.90 without calling a model."};if(!e.verified)return{headline:"Verifier failed",rule:"The verifier rejected the answer, so code caps confidence at 0.20."};if(e.status==="abstain")return{headline:n?"Field is absent from the report":"Abstained",rule:n?"The report exists but has no such field. A cited ABSENT record backs the abstention: code scores it 0.85.":"Abstained without an ABSENT record: code scores it 0.75."};if(e.status==="partial")return{headline:"Partial answer",rule:`Partial answers score 0.40, plus 0.10 per extra cited record up to 0.60. Here: ${r} cited.`};const a=e.router_mode,i=r<=1?a==="single_report"?"0.95 for one record from one report (0.90 across several reports)":"0.90 for one record":r<=3?"0.80 for two or three records":"0.70 for four or more records";return{headline:`${r} cited record${r===1?"":"s"}, verified`,rule:`Code, not the model, sets this: ${i}${o.contexts.some(t=>t.truncated)?", minus 0.05 because the context was truncated":""}. Score ${s.toFixed(2)}.`}}const d=e=>({primary:"First draft",primary_run2:"Second draft",primary_retry:"Retry",primary_run2_retry:"Retry (second draft)",escalation:"Escalation",arbiter:"Arbiter"})[e]??e;export{c,d as r};
